using Nockx.Base.CryptographyTypes;

namespace Nockx.BaseTest.NockxPublicKeyTests;

public class ConstructionTests {
	[Fact]
	public void ToStringConstructSuccess() => new NockxPublicKey(new NockxPublicKey("::").ToString());

	[Fact]
	public void ConstructSuccess() => new NockxPublicKey("::");

	[Fact]
	public void ConstructInvalidDataFail() => Assert.Throws<InvalidOperationException>(() => new NockxPublicKey("::"));
	
	[Fact]
	public void ConstructNoSeparatorsFail() => Assert.Throws<IndexOutOfRangeException>(() => new NockxPublicKey(""));

	[Fact]
	public void ConstructIncorrectKeyTypeRsaFail() => Assert.Equal("Public RSA key was attempted to be created with ML-KEM-768 key data", Assert.Throws<InvalidOperationException>(() => new NockxPublicKey("::")).Message);

	[Fact]
	public void ConstructIncorrectKeyTypeMlKemFail() => Assert.Equal("Public ML-KEM-768 key was attempted to be created with RSA key data", Assert.Throws<InvalidOperationException>(() => new NockxPublicKey("::")).Message);

	[Fact]
	public void ConstructIncorrectKeyTypeMlDsaFail() => Assert.Equal("Public ML-DSA-65 key was attempted to be created with ML-KEM-768 key data", Assert.Throws<InvalidOperationException>(() => new NockxPublicKey("::")).Message);
}